mkdir -p ~/ledger-app && cd ~/ledger-app && cat > README.md <<'EOF'
# Ledger: a tiny expense tracker for small restaurants

Built by Maya. Python 3 standard library server + vanilla JS front end.
Staff log daily expenses by category; the owner sees weekly totals and a
simple over-budget warning. No dependencies.

Run: python3 server.py  then open http://localhost:8000
EOF
cat > server.py <<'EOF'
import json
from http.server import BaseHTTPRequestHandler, HTTPServer

EXPENSES = []

class Handler(BaseHTTPRequestHandler):
    def _send(self, code, body, ctype="application/json"):
        data = body.encode() if isinstance(body, str) else body
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path == "/api/expenses":
            self._send(200, json.dumps(EXPENSES))
        elif self.path == "/api/summary":
            totals = {}
            for e in EXPENSES:
                totals[e["category"]] = totals.get(e["category"], 0) + e["amount"]
            self._send(200, json.dumps(totals))
        else:
            self._send(200, open("index.html").read(), "text/html")

    def do_POST(self):
        if self.path != "/api/expenses":
            return self._send(404, '{"error":"not found"}')
        body = json.loads(self.rfile.read(int(self.headers["Content-Length"])))
        amount = float(body.get("amount", 0))
        if amount <= 0 or not body.get("category"):
            return self._send(400, '{"error":"amount and category required"}')
        EXPENSES.append({"category": body["category"], "amount": amount, "note": body.get("note", "")})
        self._send(201, json.dumps(EXPENSES[-1]))

if __name__ == "__main__":
    HTTPServer(("", 8000), Handler).serve_forever()
EOF
cat > index.html <<'EOF'
<!doctype html>
<html><head><meta charset="utf-8"><title>Ledger</title>
<style>body{font-family:sans-serif;max-width:640px;margin:2em auto}input,select{margin:4px}</style>
</head><body>
<h1>Ledger</h1>
<form id="f">
  <input id="amount" type="number" step="0.01" placeholder="Amount" required>
  <select id="category"><option>Produce</option><option>Meat</option><option>Dairy</option><option>Labor</option><option>Utilities</option></select>
  <input id="note" placeholder="Note">
  <button>Add</button>
</form>
<h2>Totals by category</h2>
<ul id="summary"></ul>
<script>
async function refresh(){
  const r = await fetch('/api/summary'); const t = await r.json();
  document.getElementById('summary').innerHTML =
    Object.entries(t).map(([k,v]) => `<li>${k}: $${v.toFixed(2)}</li>`).join('');
}
document.getElementById('f').onsubmit = async (e) => {
  e.preventDefault();
  await fetch('/api/expenses', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({amount: document.getElementById('amount').value,
      category: document.getElementById('category').value,
      note: document.getElementById('note').value})});
  e.target.reset(); refresh();
};
refresh();
</script>
</body></html>
EOF
